import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import { targetOf } from '../utils/scopes';
import { maxSizeMb, uploadLimits } from '../utils/uploadLimits';
const t = (key, params = {}) => app.translator.trans(`walsgit-custom-heroes.admin.image.${key}`, params, true);

/** Upload, URL import and removal of a hero image. */
export default class ImageInput extends Component {
  /** What is being sent, for the right button to spin. */
  loading = null;
  url = '';
  view() {
    const {
      image,
      kind
    } = this.attrs;
    const urlId = `wch-${kind}-url`;
    return m("div", {
      className: "wch-ImageInput"
    }, m("div", {
      className: "Form-group"
    }, m("div", {
      className: "ButtonGroup wch-ImageInput-buttons"
    }, m(Button, {
      className: "Button",
      icon: "fas fa-upload",
      loading: this.loading === 'file',
      disabled: !!this.loading,
      onclick: () => this.pickFile()
    }, t('upload_button')), image && m(Button, {
      className: "Button",
      icon: "fas fa-times",
      disabled: !!this.loading,
      onclick: () => this.attrs.onchange(null)
    }, t('remove_button')), this.attrs.actions), m("p", {
      className: "helpText"
    }, t('upload_help', {
      size: maxSizeMb()
    }), " ", this.attrs.help)), m("div", {
      className: "Form-group"
    }, m("label", {
      for: urlId
    }, t('url_label')), m("div", {
      className: "wch-ImageInput-url"
    }, m("input", {
      id: urlId,
      className: "FormControl",
      type: "url",
      placeholder: "https://",
      value: this.url,
      oninput: e => this.url = e.target.value,
      onkeydown: e => {
        if (e.key === 'Enter') {
          e.preventDefault();
          this.importUrl();
        }
      }
    }), m(Button, {
      className: "Button",
      icon: "fas fa-download",
      loading: this.loading === 'url',
      disabled: !!this.loading || !this.url,
      onclick: () => this.importUrl()
    }, t('import_button'))), m("p", {
      className: "helpText"
    }, t('url_help'))));
  }
  importUrl() {
    if (this.url && !this.loading) this.send({
      url: this.url
    });
  }
  pickFile() {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'image/jpeg,image/png,image/webp';
    input.onchange = () => {
      const file = input.files?.[0];
      if (!file) return;

      // Checked here too: above PHP's limits, the request would not even reach the extension.
      if (file.size > uploadLimits().maxSize) {
        app.alerts.show({
          type: 'error'
        }, t('too_large', {
          size: maxSizeMb()
        }));
        return;
      }
      const body = new FormData();
      body.append('image', file);
      this.send(body);
    };
    input.click();
  }
  send(body) {
    const fields = {
      kind: this.attrs.kind,
      ...targetOf(this.attrs.target)
    };
    if (body instanceof FormData) {
      Object.entries(fields).forEach(([key, value]) => body.append(key, value));
    } else {
      Object.assign(body, fields);
    }
    this.loading = body instanceof FormData ? 'file' : 'url';
    app.request({
      method: 'POST',
      url: app.forum.attribute('apiUrl') + '/walsgit-custom-heroes/images',
      body,
      serialize: body instanceof FormData ? raw => raw : undefined
    }).then(image => {
      this.url = '';
      this.attrs.onchange(image);
    })
    // app.request already shows the error to the admin.
    .catch(() => {}).finally(() => {
      this.loading = null;
      m.redraw();
    });
  }
}
flarum.reg.add('walsgit-custom-heroes', 'admin/components/ImageInput', ImageInput);